        shayariItem(865, "कपड़ों से ज़्यादा सुकून आजकल ओवरसाइज़ हुडी में मिलता है,\nबिल्कुल वैसा ही जैसा तेरे गले लगने पर मिलता था।", "Gen-Z डायरी", cat, "हुडी वाइब"),
        shayariItem(866, "तेरा 'Seen' न करना भी बहुत कुछ कह जाता है,\nलगता है मेरी अहमियत अब तेरी चैट लिस्ट में नीचे खिसक गई है।", "Gen-Z डायरी", cat, "अहमियत"),
        shayariItem(867, "सच्ची मोहब्बत में कोई 'Blue Tick' या 'Last Seen' नहीं देखा जाता,\nजहाँ भरोसा हो वहाँ घंटों देर से आया रिप्लाई भी प्यार लगता है।", "Gen-Z डायरी", cat, "भरोसा"),
        shayariItem(868, "ज़िंदगी एक 'Open Book' नहीं रखनी चाहिए आजकल,\nवरना लोग पढ़ने के बहाने पन्ने मोड़कर चले जाते हैं।", "Gen-Z डायरी", cat, "सीख"),
        shayariItem(869, "तुम्हारे साथ कॉफ़ी और देर रात की हँसी,\nमेरे हिसाब से यही असली 'Luxury Lifestyle' है।", "Gen-Z डायरी", cat, "लग्ज़री"),
        shayariItem(870, "कुछ रिश्ते 'Wi-Fi' की तरह होते हैं,\nपास रहो तो सिग्नल फुल, दूर जाते ही कनेक्शन टूट जाता है।", "Gen-Z डायरी", cat, "रिश्ते"),
        shayariItem(871, "दिल की बात बताने के लिए 'Long Press' नहीं,\nबस एक सच्चा दोस्त और एक गर्म चाय का कप चाहिए।", "Gen-Z डायरी", cat, "दोस्ती"),
        shayariItem(872, "तेरे गुस्से वाला 'K' और प्यार वाला 'Kkk' पढ़ने का हुनर,\nसिर्फ़ मैं ही समझ सकता हूँ इस पूरी दुनिया में।", "Gen-Z डायरी", cat, "चैट कोड"),
        shayariItem(873, "आजकल सब 'Healing' की बात करते हैं रील्स पर,\nपर असल में हर कोई चुपचाप किसी की कमी से जूझ रहा है।", "Gen-Z डायरी", cat, "हीलिंग"),
        shayariItem(874, "तेरे साथ खींची हुई वो धुंधली सेल्फ़ी,\nमेरी पूरी गैलरी की सबसे क्लियर और प्यारी तस्वीर है।", "Gen-Z डायरी", cat, "सेल्फ़ी"),
        shayariItem(875, "कम बोलना भी आजकल एक 'Superpower' है,\nजहाँ देखो लोग बस बिना सोचे राय देने में लगे हैं।", "Gen-Z डायरी", cat, "ख़ामोशी"),
        shayariItem(876, "अगर कोई तुम्हें सुबह-सुबह अपनी मीम भेज दे,\nतो समझो नींद खुलते ही सबसे पहले तुम याद आए हो।", "Gen-Z डायरी", cat, "मीम लव"),
        shayariItem(877, "दुनिया 'Aesthetic' फोटो बनाने में लगी है,\nऔर मुझे तेरी सुबह की बिखरी जुल्फ़ें ही सबसे सुंदर लगती हैं।", "Gen-Z डायरी", cat, "एस्थेटिक"),
        shayariItem(878, "कभी-कभी बिना किसी प्लान के निकल पड़ना कार लेकर,\nपुराने गानों के साथ हर टेंशन को पीछे छोड़ आता है।", "Gen-Z डायरी", cat, "रोड ट्रिप"),
        shayariItem(879, "तुम्हारा 'Take Care' बोलना भी इतना अलग लगता है,\nजैसे पूरी दुनिया की सुरक्षा एक मैसेज में भेज दी हो।", "Gen-Z डायरी", cat, "केयर"),
        shayariItem(880, "हमने दिल का दरवाज़ा 'Private Account' जैसा रखा है,\nहर किसी को अंदर आने की रिक्वेस्ट एक्सेप्ट नहीं करते।", "Gen-Z डायरी", cat, "प्राइवेट"),
        shayariItem(881, "रात के सन्नाटे में स्क्रीन की हल्की रोशनी,\nऔर उसमें चमकती तेरी पुरानी हँसती हुई फोटो।", "Gen-Z डायरी", cat, "रात"),
        shayariItem(882, "तुम्हारे बिना ज़िंदगी बिल्कुल 'Skip Ad' जैसी हो गई है,\nबस इंतज़ार रहता है कि कब ये बुरा पल ख़त्म हो।", "Gen-Z डायरी", cat, "इंतज़ार"),
        shayariItem(883, "दोस्त वो है जो बिना 'Location' माँगे तेरे मूड पर पहुँच जाए,\nऔर एक कप चाय के साथ सारी टेंशन उड़ा दे।", "Gen-Z डायरी", cat, "यारी"),
        shayariItem(884, "आजकल प्यार भी 'Subscriber' बढ़ाने जैसा हो गया है,\nसब नंबर बढ़ाते हैं पर दिल से कोई नहीं जुड़ता।", "Gen-Z डायरी", cat, "सच"),
        shayariItem(885, "तुम्हारी हर 'Story' पर दिल वाला इमोजी नहीं भेजता मैं,\nक्योंकि मेरी पूरी मोहब्बत तो रियल लाइफ के लिए बची है।", "Gen-Z डायरी", cat, "रियल लव"),
        shayariItem(886, "चार्जिंग पर लगा फ़ोन और बगल में बैठे तुम,\nइसके आगे किसी भी मनोरंजन की ज़रूरत नहीं रहती।", "Gen-Z डायरी", cat, "सुख"),
        shayariItem(887, "ज़िंदगी में 'Auto-Correct' नहीं होता यारों,\nइसलिए बोलने से पहले दो बार सोच लेना अच्छा है।", "Gen-Z डायरी", cat, "सीख"),
        shayariItem(888, "तुम मिले तो लगा जैसे 'Algorithm' ने पहली बार सही काम किया,\nऔर मेरी सबसे बेस्ट जोड़ी बना दी।", "Gen-Z डायरी", cat, "मैच"),
        shayariItem(889, "जब भी मन उदास हो तो फोन को 'Do Not Disturb' पर डाल दो,\nऔर थोड़ी देर खुद से बातें करके देखो।", "Gen-Z डायरी", cat, "सेल्फ़ लव"),
        shayariItem(890, "किसी के लिए 'Backup Option' मत बनो कभी,\nतुम खुद में किसी के लिए 'First Choice' होने के लायक हो।", "Gen-Z डायरी", cat, "सेल्फ़ रिस्पेक्ट"),
        shayariItem(891, "सपने बड़े हैं और रास्ते में अभी थोड़ी 'Buffering' है,\nपर मेहनत पक्की है, एक दिन सब HD में दिखेगा।", "Gen-Z डायरी", cat, "हौसला"),
        shayariItem(892, "तेरे सामने आते ही मेरा 'Confidence' हमेशा क्रैश हो जाता है,\nऔर दिल बस तेरी आँखों में अटक जाता है।", "Gen-Z डायरी", cat, "क्रश"),
        shayariItem(893, "कहने को तो हम कूल और प्रैक्टिकल बनते हैं,\nपर तेरी एक छोटी सी कॉल पर बच्चे जैसे खुश हो जाते हैं।", "Gen-Z डायरी", cat, "मासूमियत"),
        shayariItem(894, "हमारी जनरेशन दिखाती है कि उसे कोई फ़र्क़ नहीं पड़ता,\nपर असल में हर कोई एक सच्चे इंसान का इंतज़ार कर रहा है।", "Gen-Z डायरी", cat, "हक़ीक़त"),
        shayariItem(895, "अगर कोई तुम्हारी लंबी-लंबी ऑडियो क्लिप पूरा सुने,\nतो समझ लेना वो इंसान तुम्हें सच में चाहता है।", "Gen-Z डायरी", cat, "प्यार"),
        shayariItem(896, "दिल टूटा तो क्या हुआ, प्लेलिस्ट तो शानदार बन गई,\nअब हर दर्द पर एक नई वाइब सेट है।", "Gen-Z डायरी", cat, "वाइब"),
        shayariItem(897, "हमने अब लोगों को 'Mute' करना सीख लिया है,\nबहस करने से ज़्यादा कीमती अपनी मानसिक शांति है।", "Gen-Z डायरी", cat, "शांति"),
        shayariItem(898, "तेरे साथ शाम के समोसे और कोल्ड कॉफ़ी का मज़ा,\nकिसी फाइव स्टार डिनर से भी ज़्यादा स्पेशल है।", "Gen-Z डायरी", cat, "डेट"),
        shayariItem(899, "हर किसी को अपनी ज़िंदगी की रील मत दिखाओ,\nकुछ प्यारे पल सिर्फ़ खुद के लिए ऑफ़लाइन बचाकर रखो।", "Gen-Z डायरी", cat, "प्राइवेसी"),
        shayariItem(900, "सच्ची वाइब वो है जहाँ दिखावा ज़ीरो हो,\nऔर तुम्हारी हँसी सौ परसेंट असली हो।", "Gen-Z डायरी", cat, "वाइब • असली")
    )
}
